```let pos = bot.entity.position;
// Set first corner
bot.chat(`//pos1 ${Math.floor(pos.x)},${Math.floor(pos.y)-1},${Math.floor(pos.z)}`);
// Set second corner (10x10)
bot.chat(`//pos2 ${Math.floor(pos.x)+9},${Math.floor(pos.y)-1},${Math.floor(pos.z)+9}`);
// Fill with stone
bot.chat('//set stone');
```

```// Create hollow glass sphere at my position
bot.chat('//hsphere glass 10');
```

```let pos = bot.entity.position;
