bot.chat(`//pos1 ${Math.floor(pos.x)-10},${Math.floor(pos.y)},${Math.floor(pos.z)-10}`);
bot.chat(`//pos2 ${Math.floor(pos.x)+10},${Math.floor(pos.y)+5},${Math.floor(pos.z)+10}`);
// Create walls
